INSERT INTO `map_project_files` VALUES (53,'fleet.yaml','fleet_sim','Gazebo ì— ë„ìš¸ ë¡œë´‡ ëª©ë¡. spawn ì¢Œí‘œëŠ” ì´ ë§µì˜ ì¶©ì „ Waypoint ì—ì„œ ê°€ì ¸ì™”ë‹¤. ê´€ì œ ë°°ì°¨ì˜ ìž…ì°° ìžê²©ì´ ë˜ëŠ” 3ì˜¨ë„ êµ¬íšë„ ì—¬ê¸° ìžˆë‹¤.',0,'# gwanghee í”„ë¡œì íŠ¸ì— ë„ìš¸ ë¡œë´‡ ëª©ë¡.\n# rmf_control_ui ê°€ ë§µ í”„ë¡œì íŠ¸ì—ì„œ ìƒì„±í–ˆë‹¤.\n#\n# spawn_x / spawn_y ëŠ” ë§µ Waypoint ì¢Œí‘œë‹¤. zones ëŠ” ì´ ë¡œë´‡ì´\n# ì§„ìž… ê°€ëŠ¥í•œ 3ì˜¨ë„ êµ¬íšìœ¼ë¡œ ê´€ì œ ë°°ì°¨ì˜ ìž…ì°° ìžê²©ì´ ëœë‹¤.\nrobots:\n  - id: PK-01\n    name: í•‘í‚¤ 1í˜¸\n    kind: mobile # ì´ë™ ë¡œë´‡\n    model: PINKY-GZ\n    gz_name: pinky_01\n    zones: [ambient, chilled, frozen]\n    home_charger: ì¶©ì „1\n    spawn_x: 1.761\n    spawn_y: -1.025\n    spawn_heading: 0.000\n  - id: OMX-02\n    name: ë§¤ë‹ˆí“°ë ˆì´í„° 2í˜¸\n    kind: workcell # ì„¤ì¹˜ ë¡œë´‡\n    model: open_manipulator_x\n    gz_name: omx_02\n    zones: []\n    station: OMX1\n    spawn_x: 0.488\n    spawn_y: -1.089\n    spawn_heading: 0.000\n  - id: OMX-03\n    name: ë§¤ë‹ˆí“°ë ˆì´í„° 3í˜¸\n    kind: workcell # ì„¤ì¹˜ ë¡œë´‡\n    model: open_manipulator_x\n    gz_name: omx_03\n    zones: []\n    station: OMX2\n    spawn_x: 0.492\n    spawn_y: -2.054\n    spawn_heading: 0.000\n','2026-08-13 00:19:03.444549'),(53,'gwanghee_bringup.launch.xml','bringup','Gazebo ì— ì´ ë§µì˜ ì›”ë“œì™€ ë¡œë´‡ì„ ì˜¬ë¦°ë‹¤. ë¡œë´‡ë§ˆë‹¤ ë„¤ìž„ìŠ¤íŽ˜ì´ìŠ¤ë¥¼ ë‚˜ëˆ  /<ë¡œë´‡>/odom ì²˜ëŸ¼ í† í”½ì„ êµ¬ë¶„í•œë‹¤.',0,'<?xml version=\'1.0\' ?>\n<!--\n  gwanghee í”„ë¡œì íŠ¸ì˜ Gazebo bringup.\n  rmf_control_ui ê°€ ë§µ í”„ë¡œì íŠ¸ì—ì„œ ìƒì„±í–ˆë‹¤.\n\n  ì›”ë“œëŠ” ë°°í¬ ì‚°ì¶œë¬¼ì„ ì“°ê³ , ë¡œë´‡ì€ ì´ í”„ë¡œì íŠ¸ì— ë“±ë¡ëœ ê²ƒë§Œ\n  ì˜¬ë¦°ë‹¤. ë¡œë´‡ë§ˆë‹¤ ë„¤ìž„ìŠ¤íŽ˜ì´ìŠ¤ë¥¼ ë‚˜ëˆ  í† í”½ì„ êµ¬ë¶„í•œë‹¤.\n-->\n<launch>\n  <arg name=\"headless\" default=\"true\"/>\n  <arg name=\"map_dir\" default=\"/home/gyi/robosapiens/rmf_maps/gwanghee\"/>\n  <arg name=\"world\" default=\"$(var map_dir)/gwanghee.world\"/>\n  <arg name=\"bridge_params\" default=\"$(var map_dir)/gwanghee_gz_bridge.yaml\"/>\n\n  <set_env name=\"GZ_SIM_RESOURCE_PATH\"\n           value=\"$(find-pkg-share pinky_description)/../:$(find-pkg-share open_manipulator_description)/../:$(var map_dir)/generated_models:$(env HOME)/.gazebo/models\"/>\n\n  <!-- í™”ë©´ì´ ì—†ëŠ” í™˜ê²½ì—ì„œëŠ” headless ë¡œ ì„œë²„ë§Œ ë„ìš´ë‹¤.\n       í—¤ë“œë¦¬ìŠ¤ ë Œë”ë§ì´ ìžˆì–´ì•¼ ë¼ì´ë‹¤Â·ì¹´ë©”ë¼ê°€ ëˆë‹¤.\n       gpu_lidar ëŠ” GPU ë¡œ ê±°ë¦¬ë¥¼ ìž¬ë¯€ë¡œ ê·¸ë¦´ ìžë¦¬ê°€ ì—†ìœ¼ë©´\n       ì•„ë¬´ê²ƒë„ ë°œí–‰í•˜ì§€ ì•ŠëŠ”ë‹¤. ì˜¤ë¥˜ë„ ë‚˜ì§€ ì•ŠëŠ”ë‹¤. -->\n  <group>\n    <include file=\"$(find-pkg-share ros_gz_sim)/launch/gz_sim.launch.py\">\n      <arg name=\"gz_args\" value=\"-r -s -v2 --headless-rendering $(var world)\"/>\n      <arg name=\"on_exit_shutdown\" value=\"true\"/>\n    </include>\n  </group>\n  <group unless=\"$(var headless)\">\n    <include file=\"$(find-pkg-share ros_gz_sim)/launch/gz_sim.launch.py\">\n      <arg name=\"gz_args\" value=\"-g -v2\"/>\n    </include>\n  </group>\n\n  <!-- PK-01 Â· í•‘í‚¤ 1í˜¸ Â· ì´ë™ ë¡œë´‡ @ ì¶©ì „1 -->\n  <include file=\"$(var map_dir)/robots/PK-01/spawn.launch.xml\"/>\n\n  <!-- OMX-02 Â· ë§¤ë‹ˆí“°ë ˆì´í„° 2í˜¸ Â· ì„¤ì¹˜ ë¡œë´‡ @ OMX1 -->\n  <include file=\"$(var map_dir)/robots/OMX-02/spawn.launch.xml\"/>\n\n  <!-- OMX-03 Â· ë§¤ë‹ˆí“°ë ˆì´í„° 3í˜¸ Â· ì„¤ì¹˜ ë¡œë´‡ @ OMX2 -->\n  <include file=\"$(var map_dir)/robots/OMX-03/spawn.launch.xml\"/>\n\n  <!-- ë‹¤ë¦¬ëŠ” í•˜ë‚˜ë¡œ ë¬¶ëŠ”ë‹¤. ì„¤ì •ì— ì´ë¦„ì´ ì ˆëŒ€ ê²½ë¡œë¡œ ì í˜€\n       ìžˆì–´ ë¡œë´‡ì´ ëª‡ ëŒ€ë“  ê²¹ì¹˜ì§€ ì•ŠëŠ”ë‹¤. -->\n  <node pkg=\"ros_gz_bridge\" exec=\"parameter_bridge\"\n        name=\"gz_bridge\" output=\"screen\"\n        args=\"--ros-args -p config_file:=$(var bridge_params)\"/>\n</launch>\n','2026-08-13 00:19:03.444549'),(53,'gwanghee_gz_bridge.yaml','bridge','Gazebo ì™€ ROS ì‚¬ì´ì˜ í† í”½ ë‹¤ë¦¬. ë¡œë´‡ë§ˆë‹¤ /<ë¡œë´‡>/odom Â· cmd_vel Â· scan ì„ ì ˆëŒ€ ì´ë¦„ìœ¼ë¡œ ì ì–´ ì—¬ëŸ¬ ëŒ€ë¥¼ ë„ì›Œë„ ê²¹ì¹˜ì