.\nSCAN_POINTS = 180\n\n# ì¹´ë©”ë¼ë¥¼ ì´ˆë‹¹ ëª‡ ìž¥ê¹Œì§€ ë‚´ë¦´ê¹Œ. ì•±ì€ 0.2ì´ˆë§ˆë‹¤ ì½ìœ¼ë¯€ë¡œ ì´ë³´ë‹¤ ë§Žì´ ë‚´ë ¤ë„\n# ë³´ì´ì§€ ì•Šê³  ë””ìŠ¤í¬ë§Œ ë¨¹ëŠ”ë‹¤.\nFRAME_INTERVAL = 1.0 / 6\n\n# ì¹´ë©”ë¼ íŒŒì¼ ë¨¸ë¦¬ê¸€. ì•±ì´ ì´ ë„¤ ê¸€ìžë¡œ íŒŒì¼ì´ ë§žëŠ”ì§€ ë³¸ë‹¤.\nFRAME_MAGIC = b\'RSIM\'\n\n\ndef write_atomic(path, data, binary=True):\n    \"\"\"ë°˜ì¯¤ ì“°ì¸ íŒŒì¼ì„ ì•±ì´ ì½ì§€ ì•Šë„ë¡ ìž„ì‹œ íŒŒì¼ì— ì“°ê³  ì˜®ê¸´ë‹¤.\"\"\"\n    tmp = path + \'.tmp\'\n    with open(tmp, \'wb\' if binary else \'w\') as handle:\n        handle.write(data)\n    os.replace(tmp, path)\n\n\nclass SensorRelay(Node):\n\n    def __init__(self, out_dir):\n        super().__init__(\'gwanghee_sensor_relay\')\n        self.out_dir = out_dir\n        self.last_frame = {}\n        os.makedirs(out_dir, exist_ok=True)\n        for robot_id, namespace in ROBOTS:\n            self.create_subscription(\n                LaserScan, f\'/{namespace}/scan\',\n                lambda msg, rid=robot_id: self.on_scan(rid, msg),\n                qos_profile_sensor_data)\n            self.create_subscription(\n                Image, f\'/{namespace}/camera/image_raw\',\n                lambda msg, rid=robot_id: self.on_image(rid, msg),\n                qos_profile_sensor_data)\n            self.get_logger().info(f\'[{robot_id}] /{namespace} ë¥¼ ë´…ë‹ˆë‹¤.\')\n\n    def on_scan(self, robot_id, msg):\n        ranges = list(msg.ranges)\n        if not ranges:\n            return\n        # ê³ ë¥´ê²Œ ì†ŽëŠ”ë‹¤. ì•žìª½ë§Œ ìž˜ë¼ë‚´ë©´ ë’¤ê°€ ì•ˆ ë³´ì¸ë‹¤.\n        step = max(1, len(ranges) // SCAN_POINTS)\n        thinned = ranges[::step]\n        # ë¬´í•œëŒ€ì™€ NaN ì€ í…ìŠ¤íŠ¸ë¡œ ì˜®ê¸°ë©´ íŒŒì„œê°€ ê±¸ë¦°ë‹¤. ìž´ ìˆ˜ ì—†ì—ˆë‹¤ëŠ” ëœ»ì´ë¯€ë¡œ\n        # ìµœëŒ€ ê±°ë¦¬ë¡œ ì ëŠ”ë‹¤.\n        cleaned = []\n        for value in thinned:\n            if value != value or value == float(\'inf\') or value > msg.range_max:\n                cleaned.append(msg.range_max)\n            else:\n                cleaned.append(value)\n        head = \'{:.6f},{:.6f},{:.3f},{:.3f}\'.format(\n            msg.angle_min, msg.angle_max, msg.range_min, msg.range_max)\n        body = \',\'.join(\'{:.3f}\'.format(value) for value in cleaned)\n        write_atomic(\n            os.path.join(self.out_dir, robot_id + \'.scan\'),\n            head + \'\\n\' + body + \'\\n\', binary=False)\n\n    def on_image(self, robot_id, msg):\n        # ì†ë„ë¥¼ ì œí•œí•œë‹¤. ì•±ì€ 0.2ì´ˆë§ˆë‹¤ ì½ìœ¼ë¯€ë¡œ ë” ìžì£¼ ë‚´ë ¤ë„ ë³´ì´ì§€ ì•ŠëŠ”ë‹¤.\n        now = self.get_clock().now().nanoseconds / 1e9\n        if now - self.last_frame.get(robot_id, 0.0) < FRAME_INTERVAL:\n            return\n        self.last_frame[robot_id] = now\n\n        pixels = self.to_rgba(msg)\n        if pixels is None:\n            return\n        header = FRAME_MAGIC + struct.pack(\'<II\', FRAME_WIDTH, FRAME_HEIGHT)\n        write_atomic(\n            os.path.join(self.out_dir, robot_id + \'.frame\'), header + pixels)\n\n    def to_rgba(self, msg):\n        \"\"\"ì˜ìƒì„ ì¤„ì—¬ì„œ RGBA ë¡œ ë§Œë“ ë‹¤.\n\n        í™”ì†Œë¥¼ íŒŒì´ì¬ ë°˜ë³µë¬¸ìœ¼ë¡œ ì˜®ê¸°ë©´ ì•ˆ ëœë‹¤. 320x180 í•œ ìž¥ì— 5ë§Œ 7ì²œ ë²ˆì´ê³ ,\n        ë‘ ëŒ€ê°€ ì´ˆë‹¹ ì—´ë‘ ìž¥ì´ë©´ ì½”ì–´ í•˜ë‚˜ë¥¼ í†µì§¸ë¡œ ë¨¹ëŠ”ë‹¤ â€” ì‹¤ì œë¡œ 101% ë¥¼\n        ì¼ë‹¤. numpy ëŠ” rclpy ê°€ ì´ë¯¸ ì“°ê³  ìžˆìœ¼ë¯€ë¡œ ìƒˆë¡œ ë°›ì„ ê²ƒì´ ì—†ë‹¤.\n        \"\"\"\n        if msg.encoding not in (\'rgb8\', \'bgr8\'):\n            self.get_logger().warn(\n                f\'ëª¨ë¥´ëŠ” ì˜ìƒ í˜•ì‹ [{msg.encoding}] ìž…ë‹ˆë‹¤.\', once=True)\n            return None\n\n        frame = np.frombuffer(msg.data, dtype=np.uint8)\n        # step ì€ í•œ ì¤„ì˜ ë°”ì´íŠ¸ ìˆ˜ë‹¤. í­ë³´ë‹¤ í´ ìˆ˜ ìžˆì–´ì„œ ìž˜ë¼ ë‚¸ë‹¤.\n        frame = frame.reshape(msg.height, msg.step)[:, :msg.width * 3]\n        frame = frame.reshape(msg.height, msg.width, 3)\n\n        # ê°€ìž¥ ê°€ê¹Œìš´ í™”ì†Œë¥¼ ì§‘ëŠ”ë‹¤. ë³´ê°„ì€ í•„ìš” ì—†ë‹¤ â€” ë³´ì—¬ ì£¼ê¸°ìš©ì´ë‹¤.\n        rows = (np.arange(FRAME_HEIGHT) * msg.height) // FRAME_HEIGHT\n        columns = (np.arange(FRAME_WIDTH) * msg.width) // FRAME_WIDTH\n        small = frame[rows][:, columns]\n        if msg.encoding == \'bgr8\':\n            small = small[:, :, ::-1]\n\n        alpha = np.full((FRAME_HEIGHT, FRAME_WIDTH, 1), 255, dtype=np.uint8)\n        return np.concatenate([small, alpha], axis=2).tobytes()\n\n\ndef main(argv=sys.argv):\n    parser = argparse.ArgumentParser(prog=\'gwanghee_sensor_relay\')\n    parser.add_argument(\'-o\', \'--out\', required=True)\n    args = parser.parse_args(rclpy.utilities.remove_ros_args(argv)[1:])\n\n    rclpy.init(args=argv)\n    node = SensorRelay(args.out)\n    if not ROBOTS:\n        node.get_logger().warn(\'ë³¼ ë¡œë´‡ì´ ì—†ìŠµë‹ˆë‹¤.\')\n    try:\n        rclpy.spin(node)\n    except KeyboardInterrupt:\n        pass\n    node.destroy_node()\n    # rclpy ì˜ ì‹ í˜¸ ì²˜ë¦¬ê¸°ê°€ ë¨¼ì € context ë¥¼ ë‹«ì•„ ë†“ëŠ” ì¼ì´ ìžˆë‹¤. ê·¸ë•Œ ë˜\n    # ë¶€ë¥´ë©´ ì˜ˆì™¸ê°€ ì˜¬ë¼ì™€, ë©€ì©¡ížˆ ëë‚œ ê²ƒì´ ì£½ì€ ê²ƒì²˜ëŸ¼ ë³´ì¸ë‹¤.\n    if rclpy.ok():\n        rclpy.shutdown()\n\n\nif __name__ == \'__main__\':\n    main(sys.argv)\n','2026-08-13 00:19:03.444549'),(53,'gwanghee_task_bridge.py','nav2','ì•±ì´ ë§Œë“  ì—°ì† ìž‘ì—…ì„ RMF ì— ë„£ì–´ ì¤€ë‹¤. RMF ëŠ” task_api_requests í† í”½ í•˜ë‚˜ë¡œ ìž‘ì—…ì„ ë°›ëŠ”ë°, ìš”ì²­ê³¼ ë‹µì„ request_id ë¡œ ë§žì¶°ì•¼ í•´ì„œ ros2 topic pub ìœ¼ë¡œëŠ” ì•ˆ ëœë‹¤. ì´ê²ƒì´ ì—†ìœ¼ë©´ ìž‘ì—…ì´ ì•± ì•ˆì—ì„œë§Œ ëŒê³  ë¡œë´‡ì€ ê°€ë§Œížˆ ìžˆëŠ”ë‹¤.',1,'#!/usr/bin/env python3\n\"\"\"gwanghee í”„ë¡œì íŠ¸ì˜ ìž‘ì—… ë‹¤ë¦¬ â€” ì•±ì´ ë§Œë“  ìž‘ì—…ì„ RMF ì— ë„£ëŠ”ë‹¤.\n\nrmf_control_ui ê°€ ë§µ í”„ë¡œì íŠ¸ì—ì„œ ìƒì„±í–ˆë‹¤. ì†ìœ¼ë¡œ ê³ ì¹˜ë©´ ë‹¤ìŒ ì €ìž¥ ë•Œ\në®ì–´ì¨ì§„ë‹¤.\n\n  gwanghee_task_bridge.py --submit ìž‘ì—….json\n\nìž‘ì—….json ì€ `robot_task_request` ë‚˜ `dispatch_task_request` í•œ ë©ì–´ë¦¬ë‹¤.\nì„±ê³µí•˜ë©´ RMF ì˜ ë‹µì„ ê·¸ëŒ€ë¡œ ì°ê³  0 ìœ¼ë¡œ ëë‚œë‹¤.\n\"\"\"\n\nimport argparse\nimport json\nimport sys\nimport uuid\n\nimport rclpy\nimport rclpy.node\nfrom rclpy.qos import QoSProfile, QoSDurabilityPolicy, QoSHistoryPolicy\n\nfrom rmf_task_msgs.msg import ApiRequest, ApiResponse\n\nFLEET_NAME = \'gwanghee_pinky\'\n\n# RMF ì˜ task API ëŠ” transient_local ì´ë‹¤. ëŠ¦ê²Œ ë¶™ëŠ” ìª½ë„ ë§ˆì§€ë§‰ ê²ƒì„ ë°›ëŠ”ë‹¤.\nAPI_QOS = QoSProfile(\n    history=QoSHistoryPolicy.KEEP_LAST,\n    depth=10,\n    durability=QoSDurabilityPolicy.TRANSIENT_LOCAL)\n\n\ndef main(argv=sys.argv):\n    parser = argparse.ArgumentParser(prog=\'gwanghee\' + \'_task_bridge\')\n    parser.add_argument(\'--submit\', required=True,\n                        help=\'ë³´ë‚¼ ìž‘ì—… JSON íŒŒì¼\')\n    parser.add_argument(\'--timeout\', type=float, default=15.0,\n                        help=\'ë‹µì„ ê¸°ë‹¤ë¦¬ëŠ” ì´ˆ\')\n    args = parser.parse_args(argv[1:])\n\n    with open(args.submit, encoding=\'utf-8\') as handle:\n        payload = json.load(handle)\n\n    rclpy.init(args=None)\n    node = rclpy.node.Node(\'gwanghee_pinky\' + \'_task_bridge\')\n    publisher = node.create_publisher(ApiRequest, \'task_api_requests\', API_QOS)\n\n    request = ApiRequest()\n    request.request_id = \'rmf_control_ui-\' + str(uuid.uuid4())[:8]\n    request.json_msg = json.dumps(payload, ensure_ascii=False)\n\n    answer = {}\n\n    def on_response(message):\n        # ë‚¨ì˜ ìš”ì²­ì— ëŒ€í•œ ë‹µë„ ê°™ì€ í† í”½ìœ¼ë¡œ ì˜¨ë‹¤.\n        if message.request_id != request.request_id:\n            return\n        answer[\'body\'] = json.loads(message.json_msg)\n\n    node.create_subscription(ApiResponse, \'task_api_responses\',\n                             on_response, API_QOS)\n\n    # êµ¬ë…ì´ ë¶™ê¸° ì „ì— ì‹¤ìœ¼ë©´ ë‹µì„ ë†“ì¹œë‹¤. í•œ ë°”í€´ ëŒë ¤ ë†“ê³  ë³´ë‚¸ë‹¤.\n    rclpy.spin_once(node, timeout_sec=0.5)\n    publisher.publish(request)\n\n    deadline = node.get_clock().now().nanoseconds + int(args.timeout * 1e9)\n    while \'body\' not in answer:\n        if node.get_clock().now().nanoseconds > deadline:\n            print(json.dumps({\n                \'success\': False,\n                \'errors\': [{\'code\': 0, \'category\': \'timeout\', \'detail\':\n                            \'RMF ê°€ ë‹µí•˜ì§€ ì•Šì•˜ìŠµë‹ˆë‹¤. fleet adapter ê°€ ë–  \'\n                            \'ìžˆëŠ”ì§€ í™•ì¸í•˜ì„¸ìš”.\'}],\n            }, ensure_ascii=False))\n            node.destroy_node()\n            if rclpy.ok():\n                rclpy.shutdown()\n            return 1\n        rclpy.spin_once(node, timeout_sec=0.2)\n\n    print(json.dumps(answer[\'body\'], ensure_ascii=False))\n    node.destroy_node()\n    if rclpy.ok():\n        rclpy.shutdown()\n    return 0 if answer[\'body\'].get(\'success\') else 1\n\n\nif __name__ == \'__main__\':\n    sys.exit(main(sys.argv))\n','2026-08-13 00:19:03.444549'),(53,'gwanghee_workcell.py','nav2','ì„¤ë¹„ ë¡œë´‡ì„ RMF ì˜ ì›Œí¬ì…€ë¡œ ìž‡ëŠ”ë‹¤. ë¡œë´‡ì´ í”½ì—… ìžë¦¬ì— ë‹¿ìœ¼ë©´ RMF ê°€ ê·¸ ìžë¦¬ ì´ë¦„ìœ¼ë¡œ ë¶€ë¥´ëŠ”ë°, ë‹µí•˜ëŠ” ë…¸ë“œê°€ ì—†ìœ¼ë©´ RMF ëŠ” ì˜ì›ížˆ ê¸°ë‹¤ë¦°ë‹¤ â€” ì˜¤ë¥˜ëŠ” ì•ˆ ë‚˜ê³  ìž‘ì—…ë§Œ ë©ˆì¶˜ë‹¤.',1,'#!/usr/bin/env python3\n\"\"\"gwanghee í”„ë¡œì íŠ¸ì˜ RMF ì›Œí¬ì…€ ì–´ëŒ‘í„°.\n\nrmf_control_ui ê°€ ë§µ í”„ë¡œì íŠ¸ì—ì„œ ìƒì„±í–ˆë‹¤. ì†ìœ¼ë¡œ ê³ ì¹˜ë©´ ë‹¤ìŒ ì €ìž¥ ë•Œ\në®ì–´ì¨ì§„ë‹¤.\n\në¡œë´‡ì´ í”½ì—… ìžë¦¬ì— ë‹¿ìœ¼ë©´ RMF ê°€ `/dispenser_requests` ë¡œ ê·¸ ìžë¦¬ ì´ë¦„ì„\në¶€ë¥¸ë‹¤. ì—¬ê¸°ì„œ íŒ”ì„ ì›€ì§ì´ê³  `/dispenser_results` ë¡œ ëë‚¬ë‹¤ê³  ë‹µí•œë‹¤.\n\në‹µí•˜ì§€ ì•Šìœ¼ë©´ RMF ëŠ” ì˜ì›ížˆ ê¸°ë‹¤ë¦°ë‹¤. ì˜¤ë¥˜ëŠ” ì•ˆ ë‚œë‹¤ â€” ìž‘ì—…ì´ ê·¸ ìžë¦¬ì—ì„œ\në©ˆì¶° ìžˆì„ ë¿ì´ë‹¤.\n\"\"\"\n\nimport sys\nimport threading\n\nimport rclpy\nimport rclpy.node\nfrom rclpy.qos import QoSProfile, QoSDurabilityPolicy, QoSReliabilityPolicy\n\nfrom builtin_interfaces.msg import Time\nfrom rmf_dispenser_msgs.msg import DispenserRequest, DispenserResult, DispenserState\nfrom rmf_ingestor_msgs.msg import IngestorRequest, IngestorResult, IngestorState\nfrom trajectory_msgs.msg import JointTrajectory, JointTrajectoryPoint\n\n# ë¡œë´‡ ID, ROS ë„¤ìž„ìŠ¤íŽ˜ì´ìŠ¤, ë§¡ì€ í”½ì—… ìžë¦¬, ë§¡ì€ ë“œëžì˜¤í”„ ìžë¦¬.\nWORKCELLS = [\n    (\'OMX-02\', \'omx_02\', [\'í”½ì—…1\'], []),\n]\n\n# íŒ”ì´ í•œ ë²ˆ ì›€ì§ì´ëŠ” ë° ê±¸ë¦¬ëŠ” ì‹œê°„ [s].\n#\n# RMF ëŠ” ì´ ì‹œê°„ì„ ëª¨ë¥¸ë‹¤. ìš°ë¦¬ê°€ ëë‚¬ë‹¤ê³  ì•Œë¦´ ë•Œê¹Œì§€ ê¸°ë‹¤ë¦´ ë¿ì´ë‹¤.\nACTION_SECONDS = 4.0\n\n# ì§‘ëŠ” ìžì„¸ì™€ ë†“ëŠ” ìžì„¸. OpenMANIPULATOR-X ì˜ ê´€ì ˆ ë„·ì´ë‹¤.\n#\n# ì‹¤ì œ ë¬¼ê±´ ìžë¦¬ì— ë§žì¶° ê³ ì³ì•¼ í•œë‹¤. ì§€ê¸ˆ ê°’ì€ íŒ”ì„ ì•žìœ¼ë¡œ ë»—ì—ˆë‹¤ ì„¸ìš°ëŠ”\n# ê²ƒë¿ì´ë¼, ë¬¼ê±´ì„ ì§‘ì§€ëŠ” ì•Šê³  **ì›€ì§ìž„ì´ ì‹¤ì œë¡œ ë‚˜ê°€ëŠ”ì§€** ë³´ëŠ” ìš©ë„ë‹¤.\nJOINT_NAMES = [\'joint1\', \'joint2\', \'joint3\', \'joint4\']\nPICK_POSE = [0.0, 0.6, -0.4, 0.8]\nHOME_POSE = [0.0, -1.0, 0.3, 0.7]\n\n\ndef now_msg(node):\n    stamp = node.get_clock().now().to_msg()\n    return Time(sec=stamp.sec, nanosec=stamp.nanosec)\n\n\nclass Workcell:\n    \"\"\"ì„¤ë¹„ í•œ ëŒ€. ë§¡ì€ ìžë¦¬ ì´ë¦„ìœ¼ë¡œ ë¶ˆë¦°ë‹¤.\"\"\"\n\n    def __init__(self, node, robot_id, namespace, dispensers, ingestors):\n        self.node = node\n        self.robot_id = robot_id\n        self.namespace = namespace\n        self.dispensers = dispensers\n        self.ingestors = ingestors\n        self.busy = False\n        self.lock = threading.Lock()\n        self.arm = node.create_publisher(\n            JointTrajectory, f\'/{namespace}/arm_controller/joint_trajectory\', 10)\n\n    def serves(self, guid):\n        return guid in self.dispensers or guid in self.ingestors\n\n    def move(self, pose, seconds):\n        \"\"\"íŒ”ì— ê´€ì ˆ ê¶¤ì ì„ ë³´ë‚¸ë‹¤.\"\"\"\n        message = JointTrajectory()\n        message.joint_names = list(JOINT_NAMES)\n        point = JointTrajectoryPoint()\n        point.positions = list(pose)\n        point.time_from_start.sec = int(seconds)\n        point.time_from_start.nanosec = int((seconds % 1) * 1e9)\n        message.points = [point]\n        self.arm.publish(message)\n\n\nclass WorkcellAdapter(rclpy.node.Node):\n\n    def __init__(self):\n        super().__init__(\'gwanghee_workcell\')\n\n        # RMF ëŠ” ìƒíƒœë¥¼ **transient local** ë¡œ ë“£ëŠ”ë‹¤. ëŠ¦ê²Œ ëœ¬ ìª½ë„ ë§ˆì§€ë§‰\n        # ìƒíƒœë¥¼ ë°›ì•„ì•¼ ì›Œí¬ì…€ì´ ìžˆë‹¤ëŠ” ê²ƒì„ ì•Œê¸° ë•Œë¬¸ì´ë‹¤.\n        state_qos = QoSProfile(\n            depth=10,\n            reliability=QoSReliabilityPolicy.RELIABLE,\n            durability=QoSDurabilityPolicy.TRANSIENT_LOCAL,\n        )\n        self.dispenser_states = self.create_publisher(\n            DispenserState, \'/dispenser_states\', state_qos)\n        self.ingestor_states = self.create_publisher(\n            IngestorState, \'/ingestor_states\', state_qos)\n        self.dispenser_results = self.create_publisher(\n            DispenserResult, \'/dispenser_results\', 10)\n        self.ingestor_results = self.create_publisher(\n            IngestorResult, \'/ingestor_results\', 10)\n\n        self.cells = [\n            Workcell(self, robot_id, namespace, dispensers, ingestors)\n            for robot_id, namespace, dispensers, ingestors in WORKCELLS\n        ]\n\n        self.create_subscription(\n            DispenserRequest, \'/dispenser_requests\',\n            lambda msg: self.on_request(msg, dispenser=True), 10)\n        self.create_subscription(\n            IngestorRequest, \'/ingestor_requests\',\n            lambda msg: self.on_request(msg, dispenser=False), 10)\n\n        # ìƒíƒœë¥¼ ì•ˆ ë‚´ë©´ RMF ê°€ ì´ ì›Œí¬ì…€ì„ ì—†ëŠ” ê²ƒìœ¼ë¡œ ë³´ê³  ìš”ì²­ì¡°ì°¨ ì•ˆ í•œë‹¤.\n        self.create_timer(1.0, self.publish_states)\n\n        served = sum(len(c.dispensers) + len(c.ingestors) for c in self.cells)\n        self.get_logger().info(\n            f\'ì›Œí¬ì…€ {len(self.cells)}ëŒ€, ë§¡ì€ ìžë¦¬ {served}ê³³ì„ RMF ì— ì´ì—ˆìŠµë‹ˆë‹¤.\')\n\n    def publish_states(self):\n        for cell in self.cells:\n            mode = DispenserState.BUSY if cell.busy else DispenserState.IDLE\n            for guid in cell.dispensers:\n                self.dispenser_states.publish(DispenserState(\n                    time=now_msg(self), guid=guid, mode=mode,\n                    request_guid_queue=[], seconds_remaining=0.0))\n            for guid in cell.ingestors:\n                self.ingestor_states.publish(IngestorState(\n                    time=now_msg(self), guid=guid, mode=mode,\n                    request_guid_queue=[], seconds_remaining=0.0))\n\n    # `handle` ì´ë¼ê³  ë¶€ë¥´ë©´ ì•ˆ ëœë‹¤. rclpy ì˜ Node ê°€ ê°™ì€ ì´ë¦„ì˜ ì†ì„±ì„\n    # ì“°ëŠ”ë°, ë©”ì„œë“œë¡œ ë®ìœ¼ë©´ Node.__init__ ì´ `with self.handle:` ì—ì„œ\n    # TypeError ë¡œ ì£½ëŠ”ë‹¤ â€” ë…¸ë“œê°€ ì•„ì˜ˆ ì•ˆ ëœ¬ë‹¤.\n    def on_request(self, msg, dispenser):\n        cell = next((c for c in self.cells if c.serves(msg.target_guid)), None)\n        if cell is None:\n            # ìš°ë¦¬ ê²ƒì´ ì•„ë‹ˆë‹¤. ë‚¨ì˜ ì›Œí¬ì…€ ìš”ì²­ì¼ ìˆ˜ ìžˆìœ¼ë¯€ë¡œ ì¡°ìš©ížˆ ë„˜ê¸´ë‹¤.\n            return\n\n        # ê°™ì€ ìš”ì²­ì´ ì—¬ëŸ¬ ë²ˆ ì˜¨ë‹¤. RMF ëŠ” ë‹µì´ ì˜¬ ë•Œê¹Œì§€ ë˜í’€ì´í•´ ë¶€ë¥¸ë‹¤.\n        with cell.lock:\n            if cell.busy:\n                return\n            cell.busy = True\n\n        self.get_logger().info(\n            f\'[{cell.robot_id}] {msg.target_guid} ìš”ì²­ ë°›ìŒ \'\n            f\'({msg.request_guid})\')\n        self.answer(msg, dispenser, DispenserResult.ACKNOWLEDGED)\n\n        cell.move(PICK_POSE, ACTION_SECONDS / 2)\n\n        def finish():\n            timer.cancel()\n            cell.move(HOME_POSE, ACTION_SECONDS / 2)\n            with cell.lock:\n                cell.busy = False\n            self.get_logger().info(f\'[{cell.robot_id}] {msg.target_guid} ë.\')\n            self.answer(msg, dispenser, DispenserResult.SUCCESS)\n\n        timer = self.create_timer(ACTION_SECONDS, finish)\n\n    def answer(self, msg, dispenser, status):\n        if dispenser:\n            self.dispenser_results.publish(DispenserResult(\n                time=now_msg(self), request_guid=msg.request_guid,\n      